mapper.select:
SELECT 
FROM ai_watch
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{ownerUserId}
ORDER BY created_at DESC, id DESC

SELECT 
FROM ai_watch
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{ownerUserId}
  AND id = #{id}

SELECT COUNT(*)
FROM ai_watch
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{ownerUserId}

mapper.update:
UPDATE ai_watch
SET status = #{status}
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{ownerUserId}
  AND id = #{id}

UPDATE ai_watch
SET last_evaluated_at = #{at}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}

UPDATE ai_watch
SET last_fired_state = #{state},
    last_fired_at = #{at}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'active'
  AND (last_fired_at IS NULL
       OR last_fired_state IS NULL
       OR last_fired_state <> #{state}
       OR last_fired_at <= #{cooldownCutoff})

mapper.delete:
DELETE FROM ai_watch
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{ownerUserId}
  AND id = #{id}

DELETE FROM ai_watch
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{userId}
